v1 = []
for i in range(2):
    try:
        v1.append(i)
        if i == 1:
            break
    finally:
        v1.append(100 + i)

print(v1)

def f1(v1):
    for i in range(v1):
        try:
            if i == 1:
                raise ValueError('gen_stop')
            yield (i + 14)
        except ValueError:
            yield 44

print(list(zip(range(2), f1(2), range(10, 10 + 2))))

